css:
.print-format { page-size: A4; orientation: Portrait; margin-top: 12mm; margin-bottom: 12mm; margin-left: 12mm; margin-right: 12mm; }
@media print { @page { size: A4 portrait; margin: 12mm; } }
/* Latin face first; the Tamil faces after it render Tamil names, remarks and Tamil prints. */
.h360-doc { font-family: "InterVariable", "Inter", "Helvetica Neue", Arial, "Noto Sans Tamil", "Noto Sans Tamil UI", "Lohit Tamil", "Tamil Sangam MN", "Latha", "Nirmala UI", sans-serif; font-size: 11px; color: #1f2933; line-height: 1.45; position: relative; }
.h360-doc table { width: 100%; border-collapse: collapse; }
.h360-doc td, .h360-doc th { vertical-align: top; }
.h360-header { border-bottom: 2px solid #1f4e79; margin-bottom: 10px; }
.h360-header td { padding-bottom: 8px; }
.h360-logo { width: 64px; }
.h360-logo img { max-width: 56px; max-height: 56px; }
.h360-institution-name { font-size: 15px; font-weight: 700; color: #1f4e79; }
.h360-muted { color: #616e7c; font-size: 10px; }
.h360-title { text-align: right; width: 34%; }
.h360-doc-title { font-size: 16px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #1f4e79; }
.h360-meta td { padding: 3px 4px; }
.h360-meta .h360-label { color: #616e7c; width: 18%; white-space: nowrap; }
.h360-lines { margin-top: 10px; }
.h360-lines th { background: #eef2f7; color: #323f4b; font-weight: 600; text-align: left; padding: 5px 6px; border-bottom: 1px solid #cbd2d9; }
.h360-lines td { padding: 5px 6px; border-bottom: 1px solid #e4e7eb; }
.h360-lines tfoot td { border-bottom: none; font-weight: 600; }
.h360-lines .h360-total td { border-top: 1px solid #9aa5b1; font-size: 12px; }
.h360-r, .h360-lines th.h360-r, .h360-lines td.h360-r { text-align: right; white-space: nowrap; }
.h360-amount-box { border: 1px solid #cbd2d9; background: #f5f7fa; padding: 8px 10px; margin: 10px 0; }
.h360-amount { font-size: 18px; font-weight: 700; color: #1f4e79; }
.h360-words { font-style: italic; color: #323f4b; }
.h360-note { margin-top: 10px; padding: 6px 8px; border-left: 3px solid #1f4e79; background: #f5f7fa; }
.h360-footer { margin-top: 14px; border-top: 1px solid #e4e7eb; }
.h360-footer td { padding-top: 6px; font-size: 10px; color: #616e7c; }
.h360-badge { display: inline-block; padding: 1px 8px; border-radius: 9px; font-size: 10px; font-weight: 600; border: 1px solid #9aa5b1; }
.h360-badge.paid { color: #0e7c3a; border-color: #0e7c3a; }
.h360-badge.overdue { color: #b42318; border-color: #b42318; }
.h360-watermark { position: absolute; top: 38%; left: 0; right: 0; text-align: center; font-size: 64px; font-weight: 700; color: rgba(180, 35, 24, 0.12); transform: rotate(-18deg); letter-spacing: 6px; }
